import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as l,o as r,X as t}from"./chunks/vendor-vueuse.XPft87tp.js";const m=JSON.parse('{"title":"分库分表、复制与读写分离","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/mysql-scaling.md","filePath":"mysql/mysql-scaling.md","lastUpdated":1786990830000}'),e={name:"mysql/mysql-scaling.md"};function i(n,o,s,d,p,g){return r(),l("div",null,o[0]||(o[0]=[t('<h1 id="分库分表、复制与读写分离" tabindex="-1">分库分表、复制与读写分离 <a class="header-anchor" href="#分库分表、复制与读写分离" aria-label="Permalink to &quot;分库分表、复制与读写分离&quot;">​</a></h1><h3 id="大表先优化-再拆库" tabindex="-1">大表先优化，再拆库 <a class="header-anchor" href="#大表先优化-再拆库" aria-label="Permalink to &quot;大表先优化，再拆库&quot;">​</a></h3><p>拆分会引入分布式事务和跨库 JOIN，不是第一选择。单表还能撑住时，按这条路径收紧：</p><ol><li>限制扫描范围，禁止无 WHERE 的大查询</li><li>索引、字段类型、冷热列拆分</li><li>缓存热点，汇总表抗统计</li><li>读写分离分担读</li><li>垂直拆：列太多或大字段拖累整行</li><li>水平拆：行太多，单表到千万、上亿还在恶化</li></ol><h3 id="垂直拆和水平拆" tabindex="-1">垂直拆和水平拆 <a class="header-anchor" href="#垂直拆和水平拆" aria-label="Permalink to &quot;垂直拆和水平拆&quot;">​</a></h3><p><strong>垂直分表</strong>：一张宽表按列拆。常用字段一张，大字段、低频字段另一张，减少 IO 和锁竞争。</p><p><strong>垂直分库</strong>：按业务拆到不同库甚至不同机器，连接数和 CPU 隔离，例如订单库、用户库。垂直拆完，单表行数仍可能很大，主键会冗余，跨表事务变难。</p><p><strong>水平分表</strong>：同一库内按规则把行拆到 <code>order_0</code>、<code>order_1</code>，解决单表过大。</p><p><strong>水平分库</strong>：行拆到不同库或机器，解决单机瓶颈；一个库挂了不至于全站写挂。</p><p>水平拆的代价是跨分片 JOIN、分布式事务、扩容迁移、全局 ID。路由键选错会把复杂度白付：只按 <code>user_id</code> 分片，运营却总按时间扫全部分片，等于每条统计都打所有库。</p><p>经验顺序：先按业务垂直拆，压力仍大再上缓存和读写分离，数据量继续涨再水平拆。</p><h3 id="分片后的全局-id" tabindex="-1">分片后的全局 ID <a class="header-anchor" href="#分片后的全局-id" aria-label="Permalink to &quot;分片后的全局 ID&quot;">​</a></h3><p>每个分片不能各自从 1 自增，需要全局唯一、尽量趋势递增的主键。</p><ul><li><strong>UUID</strong>：本地生成、无中心。太长且乱序，不适合当 InnoDB 主键</li><li><strong>号段表</strong>：单独一张发号表每次取一段，实现简单；中心库会成为瓶颈，要批量拿号缓解</li><li><strong>Redis INCR</strong>：快，要保证持久化和高可用，避免单点丢号</li><li><strong>雪花 Snowflake</strong>：64 bit = 1 位符号 + 41 位毫秒时间 + 10 位机器 + 12 位序列。趋势递增、本地生成。要处理时钟回拨和 workerId 唯一</li><li><strong>美团 Leaf</strong>：号段模式 + 雪花模式，生产里较常见</li></ul><p>主键用 <code>BIGINT</code> 雪花或号段，业务单号另存。不要把 36 位 UUID 字符串当聚簇索引。</p><h3 id="主从复制" tabindex="-1">主从复制 <a class="header-anchor" href="#主从复制" aria-label="Permalink to &quot;主从复制&quot;">​</a></h3><p>主库写 <strong>binlog</strong>，从库重放，数据跟上主库。</p><ol><li>主库提交事务时写 binlog</li><li>主库 dump 线程把 binlog 发给从库</li><li>从库 <strong>IO 线程</strong>写成 <strong>relay log</strong></li><li>从库 <strong>SQL 线程</strong>（8.0 常是协调线程 + 多个 worker）重放 relay log</li></ol><p>用途包括读扩展、高可用切换、备份、在从库做在线 DDL 或升级验证。</p><p>默认复制是<strong>异步</strong>的：主库提交成功，不代表从库已经放完，会有延迟。半同步要求至少一台从库收到 binlog 才给客户端成功，降低丢数据窗口。GTID 给每个事务全局编号，failover 更清晰。binlog 格式里 ROW 最安全，STATEMENT 可能主从不一致，MIXED 居中。</p><h3 id="读写分离" tabindex="-1">读写分离 <a class="header-anchor" href="#读写分离" aria-label="Permalink to &quot;读写分离&quot;">​</a></h3><p>读走从库，写走主库，建立在复制之上。读摊到多台后，主库锁竞争下降；从库挂了还可以留一台只读。</p><p>复制延迟是主要代价：刚写入立刻读从库，可能读不到。提交后读、强一致读要走主库，或等 GTID 追上。中间件或业务自己要能识别「写完马上读」。</p><p>从库同样建议 InnoDB，不要为了「从库用 MyISAM 更快」回退引擎。从库太多，主库 dump 也会吃资源。</p><p>读写分离解决的是读流量，不解决单表过大。表过大还是要分库分表。</p>',25)]))}const _=a(e,[["render",i]]);export{m as __pageData,_ as default};
